import{_ as t,o as a,c as n,aa as s}from"./chunks/framework.oWfRcsIL.js";const h=JSON.parse('{"title":"syslifters.ai","description":"Documentation for syslifters.ai, AI-driven penetration testing of web applications, APIs and mobile apps.","frontmatter":{"title":"syslifters.ai","description":"Documentation for syslifters.ai, AI-driven penetration testing of web applications, APIs and mobile apps."},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function r(o,e,l,d,p,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? View /llms.txt for optimized Markdown documentation, or /llms-full.txt for full documentation bundle</div><h1 id="syslifters-ai" tabindex="-1">syslifters.ai <a class="header-anchor" href="#syslifters-ai" aria-label="Permalink to &quot;syslifters.ai&quot;">​</a></h1><p>syslifters.ai runs penetration tests against web applications, APIs and Android apps with autonomous AI agents. You define a project with its scope and entry points and press <strong>Start run</strong>. Agents then map the application, look for vulnerabilities, independently verify what they find and write the results into a SysReptor report.</p><div class="danger custom-block"><p class="custom-block-title">syslifters.ai attacks the target for real</p><p>The agents are not a passive scanner. They have a full shell, send real requests, submit forms, create and modify data and log in with the accounts you provide. Treat every run like a manual penetration test by a human tester, with the same impact on the target system.</p></div><h2 id="how-a-run-works" tabindex="-1">How a run works <a class="header-anchor" href="#how-a-run-works" aria-label="Permalink to &quot;How a run works&quot;">​</a></h2><ol><li><strong>Recon.</strong> Agents start from your seed URLs and map the application: pages, endpoints, parameters, roles and technologies.</li><li><strong>Curate.</strong> The findings of recon are condensed into living documentation of the application, which you can read in the <strong>Knowledge</strong> tab.</li><li><strong>Hunt.</strong> Specialised agents test the mapped surface category by category (for example authorization, injection and session handling). New surface found during hunting is tested as well.</li><li><strong>Verify.</strong> Every suspected vulnerability is reproduced from a clean session by an independent agent. Only reproduced issues become confirmed findings.</li><li><strong>Report.</strong> Confirmed findings are written into a SysReptor project, including screenshots.</li></ol><p>You can watch every step live in the project workspace and answer approval requests while the run is in progress.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Read these pages before your first run. They cover what you are responsible for and how to avoid unwanted impact on the target.</p><ul><li><a href="/getting-started/pentest-not-a-scan">A pentest, not a vulnerability scan</a></li><li><a href="/legal/authorization">Authorization</a></li><li><a href="/legal/scope">Scope</a></li><li><a href="/legal/data-handling">Data residency and data handling</a></li><li><a href="/getting-started/test-accounts">Test systems and accounts</a></li><li><a href="/getting-started/safety-controls">Safety controls</a></li></ul><p>Then follow the <a href="/getting-started/quickstart">Quickstart</a> to run your first project.</p>',11)])])}const f=t(i,[["render",r]]);export{h as __pageData,f as default};
